{
  "findings": [
    {
      "check_id": "CKV_AZURE_123",
      "title": "Insufficient log retention period",
      "resource": "azurerm_postgresql_configuration.negative1",
      "severity": "MEDIUM",
      "explanation": "The log retention period is set to 5 days, which may not be sufficient for auditing and compliance purposes. Increasing the retention period ensures logs are available for longer durations to investigate incidents or meet regulatory requirements."
    }
  ],
  "patched_code": "resource \"azurerm_postgresql_configuration\" \"negative1\" {\n  name                = \"log_retention_days\"\n  resource_group_name = azurerm_resource_group.example.name\n  server_name         = azurerm_postgresql_server.example.name\n  value               = 30\n}",
  "fix_summary": "Increased the log retention period from 5 days to 30 days to enhance auditability and compliance."
}
